import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Flow } from 'flow-sdk';
import { 
  Input, Output, Conversion, 
  Mp4OutputFormat, BufferTarget, BlobSource, ALL_FORMATS 
} from 'mediabunny';
import { registerAc3Decoder, registerAc3Encoder } from '@mediabunny/ac3';
import { registerMp3Encoder } from '@mediabunny/mp3-encoder';
import { Sidebar } from './components/Sidebar';
import { Preview } from './components/Preview';
import { WelcomeModal } from './components/WelcomeModal';
import { Caption, AppState, StyleSettings, OutputVideo, TranscriptCache } from './types';

let encodersInitialized = false;

async function initEncoders() {
  if (encodersInitialized) return;
  registerAc3Decoder();
  registerAc3Encoder();
  registerMp3Encoder();
  encodersInitialized = true;
}

const DEFAULT_STYLE: StyleSettings = {
  mainStyle: 'Bold Pop',
  font: 'Bold Rounded',
  highlightColor: '#32CD32',
  fontSize: 'Medium',
  wordsPerLine: 2,
  textBackground: 'Soft shadow',
  animation: 'Pop',
  platform: 'Instagram Reels',
  verticalPosition: 75,
  captionOffset: 0.1,
  textSettings: {
    cleanFillerWords: true,
    emphasizeKeywords: true,
    allCaps: false,
    autoEmoji: false,
    censorProfanity: false,
  }
};

export default function App() {
  const [state, setState] = useState<AppState>({
    video: null,
    targetLanguages: ['English'],
    status: 'idle',
    currentLanguage: '',
    progress: 0,
    estimatedTime: 0,
    error: null,
    style: DEFAULT_STYLE,
    lastRenderedState: null,
    transcripts: {},
    outputs: [],
    showWelcome: true,
    showGuides: true,
  });

  useEffect(() => {
    const id = 'custom-fonts';
    if (!document.getElementById(id)) {
      const link = document.createElement('link');
      link.id = id;
      link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Caveat:wght@700&family=Inter+Tight:wght@900&family=Inter:wght@400;700&family=Noto+Sans+Arabic:wght@700&family=Noto+Sans+Devanagari:wght@700&family=Noto+Sans+Tamil:wght@700&family=Playfair+Display:wght@700&family=Roboto+Mono:wght@500&display=swap';
      document.head.appendChild(link);
    }
  }, []);

  const getFontStack = useCallback((font: StyleSettings['font']) => {
    const fonts: Record<StyleSettings['font'], string> = {
      'Bold Rounded': '"Google Sans Text", "Google Sans"',
      'Condensed Heavy': '"Inter Tight"',
      'Classic Sans': '"Inter"',
      'Elegant Serif': '"Playfair Display"',
      'Handwritten': '"Caveat"',
      'Mono': '"Roboto Mono"',
    };
    return `${fonts[font]}, "Noto Sans Tamil", "Noto Sans Devanagari", "Noto Sans Arabic", sans-serif`;
  }, []);

  const handleSelectVideo = async () => {
    try {
      const media = await Flow.media.select({ filter: 'video' });
      if (media) {
        setState(prev => ({ 
          ...prev, 
          video: media, 
          status: 'idle', 
          outputs: [], 
          transcripts: {},
          lastRenderedState: null,
          error: null 
        }));
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleDownload = async (out: OutputVideo) => {
    try {
      await Flow.download({
        base64: out.base64,
        mimeType: 'video/mp4',
        filename: `CaptionCast_${out.language}.mp4`
      });
    } catch (err) {
      console.error('Download failed', err);
    }
  };

  const processCaptions = async () => {
    if (!state.video || state.targetLanguages.length === 0) return;

    setState(prev => ({ ...prev, status: 'transcribing', progress: 0, estimatedTime: 15, error: null }));
    await initEncoders();

    const results: OutputVideo[] = [];
    const newTranscripts: TranscriptCache = { ...state.transcripts };

    try {
      for (const lang of state.targetLanguages) {
        let langCaptions: Caption[] = newTranscripts[lang];

        const needsTranscription = !langCaptions || state.lastRenderedState?.videoMediaId !== state.video.mediaId;

        if (needsTranscription) {
          setState(prev => ({ ...prev, status: 'transcribing', currentLanguage: lang, progress: 0.1, estimatedTime: 15 }));

          const settings = state.style.textSettings;
          const prompt = `Transcribe the spoken audio of this video into ${lang}. 
          Return ONLY a JSON array of word objects with 'text', 'start', 'end', 'isImportant' (optional bool), and 'emoji' (optional string).
          Rules:
          ${settings.cleanFillerWords ? '- Remove filler words.' : ''}
          ${settings.censorProfanity ? '- Censor profanity.' : ''}
          ${settings.emphasizeKeywords ? '- Flag 1-2 important words.' : ''}
          ${settings.autoEmoji ? '- Add relevant emojis.' : ''}`;

          const { text: jsonResponse } = await Flow.generate.text(prompt, {
            videos: [{ base64: state.video.base64, mimeType: state.video.mimeType }],
            systemInstruction: "You are a JSON API. Return ONLY the array."
          });

          try {
            langCaptions = JSON.parse(jsonResponse.replace(/```json|```/g, '').trim());
            newTranscripts[lang] = langCaptions;
          } catch (e) {
            throw new Error(`AI returned invalid JSON for ${lang}.`);
          }
        }

        setState(prev => ({ ...prev, status: 'rendering', currentLanguage: lang, progress: 0, estimatedTime: 10 }));

        const chunks: { words: Caption[], start: number, end: number }[] = [];
        for (let i = 0; i < langCaptions.length; i += state.style.wordsPerLine) {
          const words = langCaptions.slice(i, i + state.style.wordsPerLine);
          chunks.push({
            words,
            start: words[0].start,
            end: words[words.length - 1].end
          });
        }

        const videoBlob = await (await fetch(`data:${state.video.mimeType};base64,${state.video.base64}`)).blob();
        const input = new Input({ source: new BlobSource(videoBlob), formats: ALL_FORMATS });
        const output = new Output({
          format: new Mp4OutputFormat({ fastStart: 'in-memory' }),
          target: new BufferTarget(),
        });

        const videoTrack = await input.getPrimaryVideoTrack();
        const width = videoTrack?.displayWidth || 1280;
        const height = videoTrack?.displayHeight || 720;
        let ctx: OffscreenCanvasRenderingContext2D | null = null;

        const isRtl = lang === 'Arabic';
        const style = state.style;
        const textSettings = style.textSettings;
        const syncOffset = style.captionOffset || 0;

        const conversion = await Conversion.init({
          input,
          output,
          video: {
            width, height, fit: 'fill',
            process: (sample) => {
              if (!ctx) {
                const canvas = new OffscreenCanvas(width, height);
                ctx = canvas.getContext('2d')!;
              }
              sample.draw(ctx, 0, 0, width, height);

              const ts = sample.timestamp;
              const currentChunk = chunks.find(c => 
                ts >= (c.start + syncOffset) && 
                ts <= (c.end + syncOffset + 0.1)
              );

              if (currentChunk) {
                ctx.save();
                if (isRtl) ctx.direction = 'rtl';

                const baseSize = style.fontSize === 'Small' ? 0.04 : style.fontSize === 'Large' ? 0.08 : 0.06;
                let fontSize = Math.floor(height * (style.mainStyle === 'Hype' ? baseSize * 1.5 : baseSize));
                ctx.font = `${style.font === 'Condensed Heavy' ? '900' : 'bold'} ${fontSize}px ${getFontStack(style.font)}`;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';

                const processedWords = currentChunk.words.map(w => {
                  let text = w.text;
                  if (textSettings.allCaps) text = text.toUpperCase();
                  if (textSettings.autoEmoji && w.emoji) text += ` ${w.emoji}`;
                  return { ...w, text };
                });

                const fullText = processedWords.map(w => w.text).join(' ');
                let textWidth = ctx.measureText(fullText).width;
                const maxAllowedWidth = width * 0.9;

                let finalScale = 1;
                if (textWidth > maxAllowedWidth) {
                  finalScale = maxAllowedWidth / textWidth;
                }

                const elapsed = ts - (currentChunk.start + syncOffset);
                const animDuration = 0.25;
                let animScale = 1;
                let opacity = 1;
                let translateY = 0;

                if (elapsed < animDuration) {
                  const t = Math.max(0, elapsed / animDuration);
                  if (style.animation === 'Pop') animScale = Math.min(1, t * 1.2);
                  if (style.animation === 'Bounce') animScale = t < 0.7 ? t * 1.5 : 1 + (1 - t) * 0.2;
                  if (style.animation === 'Fade') opacity = t;
                  if (style.animation === 'Slide up') translateY = (1 - t) * (fontSize * 0.5);
                }

                const posX = width / 2;
                const safeMargin = fontSize * finalScale;
                const posY = Math.min(height - safeMargin, Math.max(safeMargin, (height * style.verticalPosition) / 100));

                ctx.translate(posX, posY - translateY);
                ctx.scale(finalScale * animScale, finalScale * animScale);
                ctx.globalAlpha = opacity;

                const padding = fontSize * 0.4;

                if (style.textBackground !== 'None') {
                  ctx.save();
                  if (style.textBackground === 'Soft shadow') {
                    ctx.shadowColor = 'rgba(0,0,0,0.8)';
                    ctx.shadowBlur = fontSize / 3;
                  } else if (style.textBackground === 'Solid bar') {
                    ctx.fillStyle = 'rgba(0,0,0,0.8)';
                    ctx.fillRect(-textWidth/2 - padding, -fontSize/2 - padding/2, textWidth + padding * 2, fontSize + padding);
                  } else if (style.textBackground === 'Blurred pill') {
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.beginPath();
                    ctx.roundRect(-textWidth/2 - padding, -fontSize/2 - padding/2, textWidth + padding * 2, fontSize + padding, fontSize);
                    ctx.fill();
                  } else if (style.textBackground === 'Outline') {
                    ctx.strokeStyle = 'black';
                    ctx.lineWidth = fontSize * 0.2;
                    ctx.strokeText(fullText, 0, 0);
                  }
                  ctx.restore();
                }

                if (style.mainStyle === 'Karaoke') {
                  const words = isRtl ? [...processedWords].reverse() : processedWords;
                  let currentX = -textWidth / 2;
                  words.forEach(w => {
                    const isActive = ts >= (w.start + syncOffset) && ts <= (w.end + syncOffset);
                    const isHighlighted = textSettings.emphasizeKeywords && w.isImportant;
                    ctx.fillStyle = isActive ? style.highlightColor : (isHighlighted ? style.highlightColor : 'white');
                    const wWidth = ctx.measureText(w.text + ' ').width;
                    ctx.fillText(w.text, currentX + wWidth/2, 0);
                    currentX += wWidth;
                  });
                } else {
                  let currentX = -textWidth / 2;
                  processedWords.forEach(w => {
                    const isHighlighted = textSettings.emphasizeKeywords && w.isImportant;
                    ctx.fillStyle = isHighlighted ? style.highlightColor : 'white';
                    const wWidth = ctx.measureText(w.text + ' ').width;
                    ctx.fillText(w.text, currentX + wWidth/2, 0);
                    currentX += wWidth;
                  });
                }
                ctx.restore();
              }
              return ctx.canvas;
            }
          }
        });

        conversion.onProgress = (p) => {
          setState(prev => ({ 
            ...prev, 
            progress: p, 
            estimatedTime: Math.max(0, Math.round(10 * (1 - p))) 
          }));
        };

        await conversion.execute();

        const resultBuffer = output.target.buffer!;
        const resultBlob = new Blob([resultBuffer], { type: 'video/mp4' });
        const base64 = await new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
          reader.readAsDataURL(resultBlob);
        });

        const saved = await Flow.save({ 
          base64, 
          mimeType: 'video/mp4', 
          name: `CaptionCast_${lang}.mp4` 
        });

        results.push({
          language: lang,
          url: URL.createObjectURL(resultBlob),
          mediaId: saved.mediaId,
          base64
        });

        setState(prev => ({ ...prev, outputs: [...results], transcripts: newTranscripts }));
      }

      setState(prev => ({ 
        ...prev, 
        status: 'complete', 
        progress: 1, 
        estimatedTime: 0,
        lastRenderedState: {
          style: JSON.stringify(state.style),
          languages: [...state.targetLanguages],
          videoMediaId: state.video?.mediaId || null
        }
      }));

    } catch (err: any) {
      console.error(err);
      setState(prev => ({ ...prev, status: 'idle', error: err.message }));
    }
  };

  const hasChanges = useMemo(() => {
    if (!state.lastRenderedState) return true;
    if (state.lastRenderedState.videoMediaId !== state.video?.mediaId) return true;
    if (JSON.stringify(state.lastRenderedState.languages) !== JSON.stringify(state.targetLanguages)) return true;
    if (state.lastRenderedState.style !== JSON.stringify(state.style)) return true;
    return false;
  }, [state.style, state.targetLanguages, state.video, state.lastRenderedState]);

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] overflow-hidden">
      <WelcomeModal 
        isOpen={state.showWelcome} 
        onClose={() => setState(prev => ({ ...prev, showWelcome: false }))} 
      />

      <Sidebar 
        state={state} 
        hasChanges={hasChanges}
        onSelectVideo={handleSelectVideo} 
        onLanguagesChange={(langs) => setState(prev => ({ ...prev, targetLanguages: langs }))}
        onStyleChange={(s) => setState(prev => ({ ...prev, style: { ...prev.style, ...s } }))}
        onProcess={processCaptions}
      />
      <div className="flex-1 flex flex-col items-center justify-center p-4 lg:p-12 bg-[#0a0a0a] overflow-hidden">
        <Preview 
          video={state.video} 
          outputs={state.outputs}
          status={state.status}
          progress={state.progress}
          estimatedTime={state.estimatedTime}
          currentLanguage={state.currentLanguage}
          platform={state.style.platform}
          verticalPosition={state.style.verticalPosition}
          showGuides={state.showGuides}
          onToggleGuides={() => setState(prev => ({ ...prev, showGuides: !prev.showGuides }))}
          onDownload={handleDownload}
          // New sync props
          transcripts={state.transcripts}
          captionOffset={state.style.captionOffset}
          onOffsetChange={(v) => setState(prev => ({ ...prev, style: { ...prev.style, captionOffset: v } }))}
          onReRender={processCaptions}
          hasChanges={hasChanges}
        />
      </div>
    </div>
  );
}

import { MediaItem } from 'flow-sdk';

export interface Caption {
  text: string;
  start: number;
  end: number;
  isImportant?: boolean;
  emoji?: string;
}

export type MainStyle = 'Bold Pop' | 'Clean Minimal' | 'Karaoke' | 'Cinematic lower-third' | 'Hype';
export type FontOption = 'Bold Rounded' | 'Condensed Heavy' | 'Classic Sans' | 'Elegant Serif' | 'Handwritten' | 'Mono';
export type FontSize = 'Small' | 'Medium' | 'Large';
export type TextBackground = 'None' | 'Soft shadow' | 'Outline' | 'Solid bar' | 'Blurred pill';
export type AnimationType = 'Pop' | 'Bounce' | 'Fade' | 'Slide up' | 'Typewriter';
export type Platform = 'Custom' | 'Instagram Reels' | 'TikTok' | 'YouTube Shorts';

export interface TextSettings {
  cleanFillerWords: boolean;
  emphasizeKeywords: boolean;
  allCaps: boolean;
  autoEmoji: boolean;
  censorProfanity: boolean;
}

export interface StyleSettings {
  mainStyle: MainStyle;
  font: FontOption;
  highlightColor: string;
  fontSize: FontSize;
  wordsPerLine: number;
  textBackground: TextBackground;
  animation: AnimationType;
  textSettings: TextSettings;
  platform: Platform;
  verticalPosition: number;
  captionOffset: number; // Offset in seconds to fix sync issues
}

export interface OutputVideo {
  language: string;
  url: string;
  mediaId: string;
  base64: string; // Stored for direct download functionality
}

export interface TranscriptCache {
  [language: string]: Caption[];
}

export interface AppState {
  video: MediaItem | null;
  targetLanguages: string[];
  status: 'idle' | 'transcribing' | 'rendering' | 'complete';
  currentLanguage: string;
  progress: number;
  estimatedTime: number; // in seconds
  error: string | null;
  style: StyleSettings;
  lastRenderedState: {
    style: string; // JSON stringified StyleSettings
    languages: string[];
    videoMediaId: string | null;
  } | null;
  transcripts: TranscriptCache;
  outputs: OutputVideo[];
  showWelcome: boolean;
  showGuides: boolean;
}

import React, { useState, useRef, useEffect } from 'react';
import { AppState, StyleSettings, MainStyle, FontOption, FontSize, TextBackground, AnimationType, TextSettings, Platform } from '../types';

interface SidebarProps {
  state: AppState;
  hasChanges: boolean;
  onSelectVideo: () => void;
  onLanguagesChange: (langs: string[]) => void;
  onStyleChange: (style: Partial<StyleSettings>) => void;
  onProcess: () => void;
}

const SectionLabel: React.FC<{ children: React.ReactNode; tooltip?: string }> = ({ children, tooltip }) => (
  <div className="flex flex-col px-2 gap-0.5">
    <span className="text-[11px] font-bold text-white/90 tracking-[0.2px] uppercase">
      {children}
    </span>
    {tooltip && (
      <span className="text-[10px] text-white/40 leading-tight">
        {tooltip}
      </span>
    )}
  </div>
);

const PillButton: React.FC<{
  icon?: React.ReactNode; children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; onClick?: () => void;
  className?: string; tooltip?: string;
}> = ({ icon, children, variant = 'filled', onClick, className = '', tooltip }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer group relative';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[11px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button title={tooltip} className={`${base} ${variants[variant]} ${className}`} onClick={onClick}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

const RangeSlider: React.FC<{
  label: string; value: number; min: number; max: number;
  step?: number; formatValue?: (val: number) => string;
  onChange: (val: number) => void; tooltip?: string;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange, tooltip }) => (
  <div className="flex flex-col gap-2 w-full px-2" title={tooltip}>
    <div className="flex items-center justify-between select-none">
      <span className="text-[11px] font-medium text-white/70 tracking-[0.1px]">{label}</span>
      <span className="text-[11px] font-medium text-white/40 tracking-[0.1px]">{formatValue(value)}</span>
    </div>
    <div className="w-full flex items-center h-2">
      <input 
        type="range" 
        min={min} 
        max={max} 
        step={step} 
        value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        className="w-full h-[3px] bg-[#595959] rounded-full appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3.5 [&::-webkit-slider-thumb]:h-3.5 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-white [&::-webkit-slider-thumb]:shadow-[0_0_8px_rgba(0,0,0,0.5)]"
      />
    </div>
  </div>
);

const Toggle: React.FC<{
  label: string;
  enabled: boolean;
  onChange: (val: boolean) => void;
  tooltip?: string;
}> = ({ label, enabled, onChange, tooltip }) => (
  <button
    type="button"
    title={tooltip}
    onClick={() => onChange(!enabled)}
    className="flex items-center justify-between w-full h-[38px] px-3 rounded-xl border border-[#595959] hover:bg-white/5 transition-all group"
  >
    <span className="text-[11px] font-medium text-white/60 group-hover:text-white transition-colors">{label}</span>
    <div className={`w-8 h-4 rounded-full relative transition-colors ${enabled ? 'bg-white' : 'bg-[#595959]'}`}>
      <div className={`absolute top-0.5 w-3 h-3 rounded-full transition-all ${enabled ? 'right-0.5 bg-black' : 'left-0.5 bg-white'}`} />
    </div>
  </button>
);

const MultiSelectDropdown: React.FC<{
  label: string; 
  selected: string[]; 
  options: string[];
  onChange: (val: string[]) => void; 
  className?: string;
  tooltip?: string;
}> = ({ label, selected, options, onChange, className = '', tooltip }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const listener = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setIsOpen(false); };
    document.addEventListener('mousedown', listener);
    return () => document.removeEventListener('mousedown', listener);
  }, []);

  const toggleOption = (opt: string) => {
    if (selected.includes(opt)) {
      if (selected.length > 1) onChange(selected.filter(s => s !== opt));
    } else {
      onChange([...selected, opt]);
    }
  };

  return (
    <div ref={ref} className={`relative ${className}`} title={tooltip}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-3 pr-1 pt-[5px] select-none focus:outline-none min-h-[49px]">
        <p className="text-[10px] font-bold text-white/30 uppercase tracking-tight">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px] truncate pr-2">
            {selected.length === 0 ? 'Select...' : selected.join(', ')}
          </span>
          <span className={`material-symbols-outlined text-[16px] text-white/30 mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#1a1a1a] border border-[#595959] rounded-xl overflow-hidden shadow-2xl animate-dropdown origin-top">
          <div className="max-h-60 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-3 py-2.5 text-[11px] font-medium tracking-[0.1px] hover:bg-white/5 transition-colors flex items-center justify-between ${selected.includes(opt) ? 'bg-white/10 text-white' : 'text-white/60'}`}
                onClick={() => toggleOption(opt)}>
                <span className="flex items-center gap-2">
                  <span className={`w-3.5 h-3.5 rounded border border-[#595959] flex items-center justify-center transition-colors ${selected.includes(opt) ? 'bg-white border-white' : ''}`}>
                    {selected.includes(opt) && <span className="material-symbols-outlined text-black text-[12px] font-bold">check</span>}
                  </span>
                  {opt}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const FieldDropdown: React.FC<{
  label: string; value: string; options: string[];
  onChange: (val: string) => void; className?: string;
  tooltip?: string;
}> = ({ label, value, options, onChange, className = '', tooltip }) => {
  const [isOpen, setIsOpen] = React.useState(false);
  const ref = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const listener = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setIsOpen(false); };
    document.addEventListener('mousedown', listener);
    return () => document.removeEventListener('mousedown', listener);
  }, []);

  return (
    <div ref={ref} className={`relative ${className}`} title={tooltip}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-3 pr-1 pt-[5px] select-none focus:outline-none h-[49px]">
        <p className="text-[10px] font-bold text-white/30 uppercase tracking-tight">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px] truncate">{value}</span>
