import React, { useState, useEffect, useRef, useMemo } from 'react';

interface CaptionSyncTimelineProps {
  base64: string;
  mimeType: string;
  firstCaptionStart: number;
  offset: number;
  onOffsetChange: (newOffset: number) => void;
  onReRender: () => void;
  hasChanges: boolean;
}

export const CaptionSyncTimeline: React.FC<CaptionSyncTimelineProps> = ({ 
  base64, mimeType, firstCaptionStart, offset, onOffsetChange, onReRender, hasChanges 
}) => {
  const [waveform, setWaveform] = useState<number[]>([]);
  const [duration, setDuration] = useState(5); // Show first 5 seconds
  const [isDragging, setIsDragging] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Analyze audio to generate a simple waveform of the beginning
  useEffect(() => {
    if (!base64) return;

    const analyzeAudio = async () => {
      try {
        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const response = await fetch(`data:${mimeType};base64,${base64}`);
        const arrayBuffer = await response.arrayBuffer();
        const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);

        // Sample the first few seconds for the sync UI
        const channelData = audioBuffer.getChannelData(0);
        const sampleRate = audioBuffer.sampleRate;
        const viewDuration = 5; // seconds
        const samplesToProcess = Math.min(channelData.length, sampleRate * viewDuration);

        const bars = 100;
        const samplesPerBar = Math.floor(samplesToProcess / bars);
        const peaks: number[] = [];

        for (let i = 0; i < bars; i++) {
          let max = 0;
          for (let j = 0; j < samplesPerBar; j++) {
            const val = Math.abs(channelData[i * samplesPerBar + j]);
            if (val > max) max = val;
          }
          peaks.push(max);
        }

        setWaveform(peaks);
        setDuration(viewDuration);
        audioCtx.close();
      } catch (err) {
        console.error('Audio analysis failed', err);
      }
    };

    analyzeAudio();
  }, [base64, mimeType]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    handleDrag(e);
  };

  const handleDrag = (e: React.MouseEvent | MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(rect.width, e.clientX - rect.left));
    const timeAtX = (x / rect.width) * duration;

    // The visual line is at (firstCaptionStart + offset)
    // So newOffset = timeAtX - firstCaptionStart
    const newOffset = timeAtX - firstCaptionStart;
    onOffsetChange(Math.max(-2, Math.min(2, newOffset)));
  };

  useEffect(() => {
    if (isDragging) {
      const onMouseMove = (e: MouseEvent) => handleDrag(e);
      const onMouseUp = () => setIsDragging(false);
      window.addEventListener('mousemove', onMouseMove);
      window.addEventListener('mouseup', onMouseUp);
      return () => {
        window.removeEventListener('mousemove', onMouseMove);
        window.removeEventListener('mouseup', onMouseUp);
      };
    }
  }, [isDragging]);

  const captionLinePos = ((firstCaptionStart + offset) / duration) * 100;

  return (
    <div className="flex flex-col gap-3 w-full animate-in fade-in slide-in-from-top-2 duration-700 delay-150">
      <div className="flex items-center justify-between px-2">
        <div className="flex items-center gap-2 group">
          <span className="material-symbols-outlined text-[16px] text-white/40">tune</span>
          <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em]">Visual Sync Tuner</span>
          <span 
            className="material-symbols-outlined text-[14px] text-white/20 hover:text-white/60 cursor-help transition-colors"
            title="Drag the yellow line to visually align the start of your captions with the audio waveforms. Use the re-render button to apply the new timing."
          >
            info
          </span>
        </div>
        <div className="flex items-center gap-4">
          <span className="text-[10px] font-bold text-white/20 uppercase tracking-widest">
            Offset: {offset > 0 ? '+' : ''}{offset.toFixed(2)}s
          </span>
          <button 
            onClick={onReRender}
            disabled={!hasChanges}
            className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${
              hasChanges 
              ? 'bg-yellow-400 text-black shadow-[0_0_15px_rgba(250,204,21,0.3)] hover:scale-105 active:scale-95' 
              : 'bg-white/5 text-white/20 cursor-not-allowed'
            }`}
          >
            <span className="material-symbols-outlined text-[14px]">refresh</span>
            Re-render
          </button>
        </div>
      </div>

      <div 
        ref={containerRef}
        onMouseDown={handleMouseDown}
        className="relative w-full h-16 bg-white/[0.02] border border-white/5 rounded-2xl overflow-hidden cursor-crosshair group"
      >
        {/* Waveform Visualization */}
        <div className="absolute inset-0 flex items-center justify-between px-1 gap-[1px]">
          {waveform.map((peak, i) => (
            <div 
              key={i} 
              className="flex-1 bg-white/10 rounded-full transition-all duration-500"
              style={{ height: `${Math.max(4, peak * 80)}%` }}
            />
          ))}
        </div>

        {/* Time Indicators */}
        <div className="absolute top-1 left-2 text-[8px] font-black text-white/10 uppercase">0.0s</div>
        <div className="absolute top-1 right-2 text-[8px] font-black text-white/10 uppercase">5.0s</div>

        {/* Caption Start Line */}
        <div 
          className="absolute top-0 bottom-0 w-0.5 bg-yellow-400 shadow-[0_0_15px_rgba(250,204,21,0.5)] z-10 pointer-events-none"
          style={{ left: `${Math.max(0, Math.min(100, captionLinePos))}%` }}
        >
          <div className="absolute -top-1 -left-1.5 w-3.5 h-3.5 bg-yellow-400 rounded-full border-2 border-[#0e0e0e]" />
          <div className="absolute -bottom-1 -left-1.5 w-3.5 h-3.5 bg-yellow-400 rounded-full border-2 border-[#0e0e0e]" />

          <div className="absolute top-2 left-3 bg-yellow-400 text-black px-1.5 py-0.5 rounded text-[8px] font-black uppercase tracking-tighter whitespace-nowrap shadow-sm">
            Captions Start
          </div>
        </div>

        {/* Drag Hint */}
        <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
          <span className="text-[9px] font-bold text-white/30 uppercase tracking-[0.3em] bg-[#0e0e0e]/60 px-4 py-1 rounded-full backdrop-blur-sm">
            Drag to align with audio peaks
          </span>
        </div>
      </div>
    </div>
  );
};
